update pages set contenu = '{"sections":[{"type":"heros","h1":"Montage industriel : machines, lignes et équipements de production","mecanisme":"**Votre équipement neuf produit, il n''attend pas.** Monté, calé, raccordé, essayé.","cta":"Faire chiffrer mon montage","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30"},{"type":"chiffres","chiffres":[{"valeur":"+ 100","libelle":"collaborateurs · techniciens salariés Migen, pas de chaîne d''intermédiaires."},{"valeur":"+ 120","libelle":"clients industriels · dont plus de 80 qui reviennent chaque année."},{"valeur":"4","libelle":"agences · Lyon (siège), Montréal, Dubaï, Madrid, et des hubs techniques en France."},{"valeur":"10 %","libelle":"des candidats retenus · entretien technique et entretien comportemental, résultats partagés avec vous."}]},{"type":"probleme","punchline":"Une machine livrée n''est pas une machine qui produit.","puces":[{"accroche":"Vos meilleurs techniciens détournés de la production.","texte":"Pour monter le neuf, on déshabille l''existant. Le préventif saute, l''arriéré grossit."},{"accroche":"Un montage confié au moins-disant.","texte":"Il assemble, il ne raccorde pas. Le constructeur revient facturer la mise en service."},{"accroche":"Les réserves qui traînent.","texte":"La ligne tourne à 70 %, et plus personne ne sait à qui appartient le problème."},{"accroche":"La cascade de sous-traitance.","texte":"Vous ne savez plus qui monte réellement votre machine, ni selon quel standard."}]},{"type":"offre","lignes":[{"prestation":{"texte":"**Réception et contrôle à la livraison**"},"benefice":"Colisage vérifié, manquants relevés au bon moment. Une réserve signalée le jour J se règle, une réserve découverte au montage se discute."},{"prestation":{"texte":"**Assemblage mécanique**"},"benefice":"Châssis, convoyeurs, sous-ensembles, tuyauterie, chaudronnerie. Montage selon les plans du constructeur, pas selon une méthode générique."},{"prestation":{"texte":"**Calage, alignement et scellements**"},"benefice":"Mise à niveau, alignement, ancrage. Ce qui se règle mal au montage devient une usure qui revient tous les six mois."},{"prestation":{"texte":"**Raccordements électriques et armoires**"},"benefice":"Tirage, raccordement, repérage, contrôles. Une installation repérable est une installation dépannable."},{"prestation":{"texte":"**Raccordements fluides**"},"benefice":"Hydraulique, pneumatique, air comprimé, circuits de lubrification. Mise en pression et recherche de fuites avant la production."},{"prestation":{"texte":"**Automatisme et robotique**"},"benefice":"Mise sous tension, chargement des programmes, contrôle des sécurités. Automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc."},{"prestation":{"texte":"**Implantation industrielle et installation de ligne de production**"},"benefice":"Plan d''implantation respecté, circulation des matières vérifiée, postes opérateurs accessibles. La ligne est utilisable, pas seulement montée."},{"prestation":{"texte":"**Essais et accompagnement du démarrage**"},"benefice":"Essais à vide, essais en charge, réglages, levée des réserves. Le montage se termine quand la ligne produit."},{"prestation":{"texte":"**Montage pour compte de fabricants**"},"benefice":"Vous vendez partout, nous installons partout. Équipes mobiles, standards constructeur, un seul interlocuteur."}]},{"type":"deroule","etapes":[{"titre":"Lecture du dossier technique.","texte":"Plans constructeur, notice de montage, plan d''implantation, contraintes du site. Les écarts se repèrent là, pas sur le chantier."},{"titre":"Préparation du site.","texte":"Accès, sols, massifs, alimentations, moyens de [levage et de manutention lourde](/travaux-industriels/levage-manutention/) dimensionnés pour les charges réelles."},{"titre":"Réception et mise en place.","texte":"Déchargement, contrôle du colisage, mise en position des ensembles lourds."},{"titre":"Assemblage.","texte":"Montage mécanique, chaudronnerie et tuyauterie, dans l''ordre imposé par le constructeur."},{"titre":"Calage et raccordements.","texte":"Alignement, scellements, raccordements électriques, fluides et automatisme, avec repérage complet."},{"titre":"Essais et réglages.","texte":"Essais à vide, sécurités, essais en charge, réglages de production."},{"titre":"Réception et dossier.","texte":"Levée des réserves avec votre exploitant, plans et repérages remis à jour, compte rendu de chantier."}]},{"type":"garanties","puces":[{"accroche":"Celui qui monte est un salarié Migen.","texte":"Pas de sous-traitance en cascade : celui qui assemble est celui qui répond de son assemblage."},{"accroche":"Le montage suit les plans du constructeur.","texte":"Quand un plan est incohérent avec le terrain, nous le disons avant de percer, pas après."},{"accroche":"Le chantier finit avec un dossier.","texte":"Repérages, plans à jour, réserves levées. Votre équipe de maintenance récupère une machine qu''elle peut dépanner seule."}]},{"type":"cta","question":"Besoin d''une équipe de montage disponible sur votre prochain chantier ?","bouton":"Faire chiffrer mon montage","href":"/contact/","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30, astreinte 24/24 et 7/7."},{"type":"preuves","preuves":[{"titre":"Montage d''un centre logistique, Clermont-Ferrand, 2023.","texte":"12 monteurs mécaniciens et 8 engins de levage mobilisés en pleine période estivale, site livré à la date prévue","lienLibelle":"Étude de cas AKTID","lienHref":"/preuves/aktid-centre-logistique/"},{"titre":"Montage de portiques de lavage pour un fabricant, partout en France.","texte":"Réception, assemblage, levage, raccordements mécaniques et électriques, portique validé à l''issue du montage","lienLibelle":"Étude de cas ORTHUS x WASHTEC","lienHref":"/preuves/orthus-washtec/"},{"titre":"Montage et déplacement de machines, étanchéité et isolation, 2025.","texte":"Assemblage mécanique et électromécanique de lignes et de sous-ensembles, délais tenus sans pénalité","lienLibelle":"Étude de cas SOPREMA","lienHref":"/preuves/soprema/"},{"titre":"Construction d''un site de R&D bas carbone, région parisienne.","texte":"Mise en place des équipements et raccordements industriels, pilotés par Orthus, filiale du groupe","lienLibelle":"Étude de cas ORTHUS x ECOCEM","lienHref":"/preuves/orthus-ecocem/"},{"titre":"Contrôle de chantier, projets stratégiques, 2025 à 2026.","texte":"Vérification des installations et respect des procédures sur des systèmes automatisés","lienLibelle":"Étude de cas ALSTEF Group","lienHref":"/preuves/alstef-group/"}]},{"type":"objections","questions":[{"question":"Combien coûte un montage industriel ?","reponse":"Le montant dépend du nombre d''ensembles, de leur poids, des raccordements à réaliser et du niveau d''essais attendu. Chiffrage sur devis après lecture du dossier technique et visite du site, poste par poste."},{"question":"Concevez-vous ou fabriquez-vous des machines ?","reponse":"Non. Nous montons des équipements conçus et fabriqués par d''autres, selon leurs plans et leurs standards. C''est un choix : notre métier est la maintenance industrielle, et avec elle le montage et la remise en service."},{"question":"Travaillez-vous pour des fabricants d''équipements ?","reponse":"Oui. Un fabricant qui vend sur tout le territoire doit installer sur tout le territoire. Nos équipes montent chez ses clients, formées à ses équipements, sans sous-traitance en cascade."},{"question":"Que recouvre une implantation industrielle ?","reponse":"Le placement des équipements dans l''atelier : circulation des matières, accès de maintenance, postes opérateurs, réseaux et énergies. Le plan est validé avant le montage, parce qu''une machine mal placée se corrige à l''arrêt suivant."},{"question":"Pouvez-vous renforcer notre équipe de montage plutôt que tout prendre ?","reponse":"Oui. Des techniciens intégrés à votre équipe projet, encadrés par Migen, sur la durée du pic de charge. C''est ce que nous faisons pour le contrôle de chantier chez ALSTEF Group."},{"question":"Qui sont les techniciens qui interviennent ?","reponse":"Des salariés Migen, évalués en entretien technique et en entretien comportemental. Seuls 10 % des candidats sont retenus. Monteurs mécaniciens, électriciens, automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc."}]},{"type":"ctaFinal","question":"Besoin de monter une ligne sans vider votre atelier de ses techniciens ?","bouton":"Parler à un chargé d''affaires","href":"/contact/","rappel":"04 78 33 72 05, astreinte 24/24 et 7/7."}]}'::jsonb where path = '/travaux-industriels/montage-industriel/';
